Here is the commit message:
IB/qib: Remove qpt_mask global

There is no need to have a global qpt_mask as that does not support the
multiple chip model which qib has. Instead rely on the value which
exists already in the device data (dd).

Fixes: 898fa52b4ac3 "IB/qib: Remove qpn, qp tables and related variables from qib"
Reviewed-by: Mike Marciniszyn <mike.marciniszyn@intel.com>
Signed-off-by: Dennis Dalessandro <dennis.dalessandro@intel.com>
Signed-off-by: Doug Ledford <dledford@redhat.com>

Here is the root cause:
The root cause of the bug was the reliance on a global variable `qpt_mask`, which did not support the multiple chip model of the qib driver. This global state could lead to incorrect behavior when multiple devices were used simultaneously, as they would share the same `qpt_mask` value, potentially causing conflicts and incorrect resource allocation.

Here is the patch:
 #include "qib.h"

-/*
- * mask field which was present in now deleted qib_qpn_table
- * is not present in rvt_qpn_table. Defining the same field
- * as qpt_mask here instead of adding the mask field to
- * rvt_qpn_table.
- */
-u16 qpt_mask;
-
 static inline unsigned mk_qpn(struct rvt_qpn_table *qpt,
 			      struct rvt_qpn_map *map, unsigned off)
 {
 	return (map - qpt->map) * RVT_BITS_PER_PAGE + off;
 }

 static inline unsigned find_next_offset(struct rvt_qpn_table *qpt,
 					struct rvt_qpn_map *map, unsigned off,
-					unsigned n)
+					unsigned n, u16 qpt_mask)
 {
 	if (qpt_mask) {
 		off++;
 		if (((off & qpt_mask) >> 1) >= n)
 			off = (off | qpt_mask) + 2;
 	} else {
 		off = find_next_zero_bit(map->page, RVT_BITS_PER_PAGE, off);
 	}
 	return off;
 }

  */
 int qib_alloc_qpn(struct rvt_dev_info *rdi, struct rvt_qpn_table *qpt,
 		  enum ib_qp_type type, u8 port, gfp_t gfp)
 {
 	u32 i, offset, max_scan, qpn;
 	struct rvt_qpn_map *map;
 	u32 ret;
 	struct qib_ibdev *verbs_dev = container_of(rdi, struct qib_ibdev, rdi);
 	struct qib_devdata *dd = container_of(verbs_dev, struct qib_devdata,
 					      verbs_dev);
+	u16 qpt_mask = dd->qpn_mask;

 	if (type == IB_QPT_SMI || type == IB_QPT_GSI) {
 		unsigned n;

 		ret = type == IB_QPT_GSI;
 		n = 1 << (ret + 2 * (port - 1));
 		spin_lock(&qpt->lock);
 		if (qpt->flags & n)
 			ret = -EINVAL;
 		else
 			qpt->flags |= n;
 		spin_unlock(&qpt->lock);
 		goto bail;
 	}

 	qpn = qpt->last + 2;
 	if (qpn >= RVT_QPN_MAX)
 		qpn = 2;
 	if (qpt_mask && ((qpn & qpt_mask) >> 1) >= dd->n_krcv_queues)
 		qpn = (qpn | qpt_mask) + 2;
 	offset = qpn & RVT_BITS_PER_PAGE_MASK;
 	map = &qpt->map[qpn / RVT_BITS_PER_PAGE];
 	max_scan = qpt->nmaps - !offset;
 	for (i = 0;;) {
 		if (unlikely(!map->page)) {
 			get_map_page(qpt, map, gfp);
 			if (unlikely(!map->page))
 				break;
 		}
 		do {
 			if (!test_and_set_bit(offset, map->page)) {
 				qpt->last = qpn;
 				ret = qpn;
 				goto bail;
 			}
 			offset = find_next_offset(qpt, map, offset,
-				dd->n_krcv_queues);
+				dd->n_krcv_queues, qpt_mask);
 			qpn = mk_qpn(qpt, map, offset);
 			/*
 			 * This test differs from alloc_pidmap().
 			 * If find_next_offset() does find a zero
 			 * bit, we don't need to check for QPN
 			 * wrapping around past our starting QPN.
 			 * We just need to be sure we don't loop
 			 * forever.
 			 */
 		} while (offset < RVT_BITS_PER_PAGE && qpn < RVT_QPN_MAX);
 		/*
 		 * In order to keep the number of pages allocated to a
 		 * minimum, we scan the all existing pages before increasing
 		 * the size of the bitmap table.
 		 */
 		if (++i > max_scan) {
 			if (qpt->nmaps == RVT_QPNMAP_ENTRIES)
 				break;
 			map = &qpt->map[qpt->nmaps++];
 			offset = 0;
 		} else if (map < &qpt->map[qpt->nmaps]) {
 			++map;
 			offset = 0;
 		} else {
 			map = &qpt->map[0];
 			offset = 2;
 		}
 		qpn = mk_qpn(qpt, map, offset);
 	}

 	ret = -ENOMEM;

 bail:
 	return ret;
 }



